function Get-RestorePlan {
    param([Parameter(Mandatory)]$Backup)

    $backupFull = [IO.Path]::GetFullPath($Backup.Directory.FullName).TrimEnd('\') + '\'
    $payloadRoot = Join-Path $Backup.Directory.FullName 'SaveGames'
    if (-not (Test-Path -LiteralPath $payloadRoot -PathType Container)) {
        throw "reass: ass backup payload is missing: $payloadRoot"
