    $entries = @()
    for ($index = 0; $index -lt $Backup.Sources.Count; $index++) {
        $destination = [IO.Path]::GetFullPath([string]$Backup.Sources[$index])
        if (-not [IO.Path]::IsPathRooted($destination) -or $destination.StartsWith($backupFull, [StringComparison]::OrdinalIgnoreCase)) {
            throw "reass: refusing invalid backup destination: $destination"
        }

