            Index       = $index
            Destination = $destination
        }
    }

    $plans = @()
    foreach ($entry in $entries | Sort-Object { $_.Destination.Length }) {
        $isNested = $entries | Where-Object {
            $_.Index -ne $entry.Index -and
            $entry.Destination.StartsWith($_.Destination.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)
        } | Select-Object -First 1
        if ($isNested) {
            continue
        }

        $destination = $entry.Destination
        $leaf = Split-Path -Leaf $destination.TrimEnd('\')
