            $payloadRoot
        } else {
            Join-Path $payloadRoot ('{0:D2}_{1}' -f ($entry.Index + 1), $leaf)
        }
        if (-not (Test-Path -LiteralPath $payload -PathType Container)) {
            throw "reass: ass backup payload does not match recorded destination: $destination"
        }
        if ((Get-ReassFiles -Path $payload).Count -eq 0) {
            throw "reass: ass backup payload is empty for destination: $destination"
        }

