        if ([string]::IsNullOrWhiteSpace($parent)) {
            throw "reass: refusing root destination: $destination"
        }
        $plans += [pscustomobject]@{
            Source      = $payload
            Destination = $destination
            Stage       = Join-Path $parent ((Split-Path -Leaf $destination) + '.reass-stage-' + $runId + '-' + $entry.Index)
            Rollback    = Join-Path $parent ((Split-Path -Leaf $destination) + '.reass-rollback-' + $runId + '-' + $entry.Index)
            Activated   = $false
